def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_my, last_opp = history[-1]

    oppD = 0
    for _, o in history:
        if o == 'D':
            oppD += 1

    streakD = 0
    i = n - 1
    while i >= 0:
        if history[i][1] == 'D':
            streakD += 1
            i -= 1
        else:
            break

    rec5D = 0
    for _, o in history[-5:]:
        if o == 'D':
            rec5D += 1

    if streakD >= 5:
        return 'D'

    if n >= 20 and oppD * 10 > n * 7 and rec5D >= 2:
        return 'D'

    if oppD == 0 and n >= 12:
        return 'D'

    if last_my == 'D' and last_opp == 'C' and rec5D == 0 and oppD <= max(2, n // 10):
        return 'D'

    if last_opp == 'C' and rec5D == 0 and oppD <= max(2, n // 10) and n >= 30 and rng.random() < 0.02:
        return 'D'

    if last_opp == 'C':
        return 'C'

    if last_my == 'D':
        return 'C'

    if streakD == 1:
        if oppD <= max(2, n // 8):
            return 'C'
        return 'D'

    if streakD == 2:
        return 'D'

    if streakD == 3:
        if oppD <= max(3, n // 5):
            return 'C'
        return 'D'

    if streakD == 4:
        if oppD <= max(6, n // 3):
            return 'C'
        return 'D'

    return 'D'
